 function changeText(value){setText(value);if(!ready||!peer)return;clearTimeout(typingTimer.current);setTyping(user.user_id,peer.user_id,Boolean(value.trim())).catch(e=>setError(e.message));if(value.trim())typingTimer.current=setTimeout(()=>setTyping(user.user_id,peer.user_id,false).catch(()=>{}),1500);}
 async function send(e){e.preventDefault();setSending(true);clearTimeout(typingTimer.current);try{await setTyping(user.user_id,peer.user_id,false);await sendMessage(user.user_id,peer.user_id,text);setText('');setError('');}catch(e){setError(e.message);}finally{setSending(false);}}
 const presenceText=peerTyping?'Typing…':peerPresence.state==='online'?'Active now':peerPresence.lastChanged?`Last active ${new Date(peerPresence.lastChanged).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}`:'Offline';
