 return <><div className="page-heading"><span className="eyebrow">LET'S START A CONVERSATION</span><h1>A simple hello goes a long way<span>.</span></h1><p>Talk directly with landlords and future roommates.</p></div><ErrorBox error={error}/><div className="chat-layout"><aside className="contacts"><h3>People</h3><input aria-label="Search people" placeholder="Find a person…" value={search} onChange={e=>setSearch(e.target.value)}/><div>{contacts.filter(c=>`${c.first_name} ${c.last_name}`.toLowerCase().includes(search.toLowerCase())).map(c=>{const unread=Number(unreadByPeer[String(c.user_id)]||0);return <button className={peer?.user_id==c.user_id?'contact selected':'contact'} onClick={()=>{setPeer(c);setError('');}} key={c.user_id}><span className="avatar">{c.first_name[0]}</span><span className="contact-copy"><strong>{c.first_name} {c.last_name}</strong><small>{c.role}</small></span>{unread>0&&<span className="contact-unread-badge" aria-label={`${unread} unread messages`}>{unread>99?'99+':unread}</span>}</button>;})}</div></aside><section className="chat-main">{peer?<><div className="chat-header"><span className={`avatar ${peerPresence.state==='online'?'online-avatar':''}`}>{peer.first_name?.[0]}{peerPresence.state==='online'&&<i className="online-dot"/>}</span><div><strong>{peer.first_name} {peer.last_name}</strong><small className={peerTyping?'typing-text':''}>{presenceText}</small></div></div><div className="messages" ref={node=>{if(node)node.scrollTop=node.scrollHeight;}}>{messages.length?messages.map(m=>{const mine=String(m.sender)===String(user.user_id);return <div className={mine?'bubble mine':'bubble'} key={m.id}><p>{m.text}</p><small>{m.createdAt?new Date(m.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}):'Sending…'}{mine&&<span className="message-receipt"> · {messageStatus(m)}</span>}</small></div>}):<Busy>{ready?'Say hello and start your conversation.':'Waiting for Firebase connection.'}</Busy>}{peerTyping&&<div className="typing-bubble" aria-label={`${peer.first_name} is typing`}><i/><i/><i/></div>}</div><form className="composer" onSubmit={send}><input aria-label="Message" maxLength={2000} placeholder="Write a message…" value={text} onChange={e=>changeText(e.target.value)} disabled={!ready}/><button disabled={!ready||!text.trim()||sending}>{sending?'Sending…':'Send'} <ArrowUpRight size={16}/></button></form></>:<Busy>Choose a person to start chatting.</Busy>}</section></div></>;
