 return <><div className="page-heading"><span className="eyebrow">KEEP YOUR NEXT STEPS TOGETHER</span><h1>{owner(user)?'Your incoming inquiries':'Your housing inquiries'}<span>.</span></h1><p>Keep track of responses and continue the conversation.</p></div><ErrorBox error={error}/>{notice&&<p className="success">{notice}</p>}{busy?<Busy loading/>:rows.length?rows.map(i=><article className="inquiry panel" key={i.inquiry_id}><div><span className="eyebrow">{new Date(i.created_at.replace(' ','T')).toLocaleDateString()}</span><h3>{i.title}</h3>{owner(user)&&<div className="inquiry-contact"><strong>{i.first_name} {i.last_name}</strong><span>{i.phone||'No phone added'}</span><span>{i.email}</span></div>}<p>{i.message}</p><span className="status">{label(i.status)}</span>{i.rent_end&&<p>Rent ends: {i.rent_end}</p>}{i.contract_id&&<ContractPanel id={i.contract_id} user={user}/>}{owner(user)&&i.status==='accepted'&&!i.contract_id&&<ContractCreator inquiry={i} onDone={load}/>}</div><div className="inquiry-actions">{owner(user)&&<select aria-label="Inquiry status" value={i.status} disabled={busy||i.status!=='pending'} onChange={e=>status(i,e.target.value)}><option value="pending">Pending</option><option value="accepted">Accepted</option><option value="declined">Rejected</option></select>}<button className="outline" onClick={()=>chat({user_id:owner(user)?i.applicant_id:i.owner_id,first_name:owner(user)?i.first_name:'Landlord',last_name:owner(user)?i.last_name:''})}>Message <MessageCircle size={16}/></button></div></article>):<Busy>No inquiries yet.</Busy>}</>;
